import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"有限状态机","description":"","frontmatter":{"title":"有限状态机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fsm-control.md","filePath":"cs/fsm-control.md","lastUpdated":1789023840000}'),E={name:"cs/fsm-control.md"};function h(m,a,_,S,f,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="有限状态机" tabindex="-1">有限状态机 <a class="header-anchor" href="#有限状态机" aria-label="Permalink to &quot;有限状态机&quot;">​</a></h1><div class="epigraph"><p>现态存在寄存器里，下一态与输出都是现态和输入的组合函数；控制器先画成这样一份图。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/register-shift">寄存器与移位</a>钉死了 \\(n\\) 位使能寄存器。本课不重讲桶形移位，也不从自动机理论的正则语言另起。缺口是：寄存器可以存任何比特，还没有约定这些比特表示<strong>控制步骤</strong>。后课多周期 CPU、总线协议、外设，都要把步骤画成有限状态机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合网瞬时，时序需要「现在处于哪一步」。缺口是 FSM：有限状态集 \\(S\\)，输入字母、输出字母，转移 \\(\\delta:S\\times\\Sigma\\to S\\)，输出 \\(\\lambda\\) 或 Moore 的 \\(\\lambda:S\\to\\) 输出。现态用 \\([\\log_2|S|]\\) 位寄存器（或独热）。下一态逻辑与输出逻辑是组合，必须满足建立保持。</p><p>Mealy 输出依赖输入，路径更短或更长取决于是否把输入算进关键路径；Moore 输出只看状态，往往更稳、多一拍。本课两种都承认，后课控制器常用混合。</p><h3 id="状态图不是程序流程图" tabindex="-1">状态图不是程序流程图 <a class="header-anchor" href="#状态图不是程序流程图" aria-label="Permalink to &quot;状态图不是程序流程图&quot;">​</a></h3><p>边是时钟拍上的转移，不是「函数调用」。无时钟的异步状态机不在主干。把 FSM 画成可以停留在组合环里等握手而无状态寄存器，会绕过上一课的 FF。</p><p><span class="marginnote">Harris 用交通灯、序列检测当例子。后课多周期取指/译码/执行是同一套：每个圆圈一拍。本课不引入微程序 ROM，那是更后一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列状态、编码、画 \\(\\delta\\) 与 \\(\\lambda\\) 的真值表，用卡诺图或 HDL 综合成下一态与输出组合，接到寄存器 D 端。复位把状态送到已知编码。</p>',11)),(e(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20NS%5B%22%E4%B8%8B%E4%B8%80%E6%80%81%E7%BB%84%E5%90%88%22%5D%0A%20%20ST%5B%22%E7%8E%B0%E6%80%81%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20NS%0A%20%20NS%20--%3E%20ST%0A%20%20ST%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E7%BB%84%E5%90%88%22%5D%0A%20%20IN%20--%3E%20OUT%0A%20%20OUT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AE%A1%E6%95%B0%E5%99%A8%E7%89%B9%E4%BE%8B%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独热编码让输出常是单触发器，下一态逻辑简单，FF 用得多。二进制编码省 FF，译码更重。后课控制真值表可以是「指令 × 状态」的大 ROM，仍是本课 FSM 的实现。非法状态应导向复位或陷阱，与无关项政策一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证正则语言等价、不把下推自动机请进来。不讨论状态最小化算法细节。连续控制、PID 不是 FSM。</p><p>后课默认：控制器是同步 FSM；现态在寄存器，转移每拍一次。计数器是状态沿环走的特例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FSM = 状态寄存器 + 下一态/输出组合。</li><li>Moore/Mealy 差在输出是否看输入。</li><li>编码在独热与二进制之间权衡。</li><li>出处：Harris and Harris。</li></ul>',7))])}const T=i(E,[["render",h]]);export{B as __pageData,T as default};
